export function validateAttemptsExhaustedPlanRetryDecisionEvidence(value: unknown, path: string, contract: string): void {
  if (!isRecord(value)) fail(contract, path, "expected object");
  const record = value as JsonRecord;
  if (!Object.hasOwn(record, "exit_code")) fail(contract, `${path}.exit_code`, "missing required property");
  if (!Object.hasOwn(record, "policy_reason")) fail(contract, `${path}.policy_reason`, "missing required property");
  for (const [key, item] of Object.entries(record)) {
    switch (key) {
        case "disposition": {
          if (item !== "ATTEMPTS_EXHAUSTED") fail(contract, `${path}.disposition`, "did not match required constant");
          if (typeof item !== "string") fail(contract, `${path}.disposition`, "expected string");
          break;
        }
        case "exit_code": {
          if (typeof item !== "number" || !Number.isFinite(item)) fail(contract, `${path}.exit_code`, "expected finite number");
          if (!Number.isInteger(item)) fail(contract, `${path}.exit_code`, "expected integer");
          break;
        }
        case "policy_reason": {
          if (typeof item !== "string") fail(contract, `${path}.policy_reason`, "expected string");
          if ((item as string).length < 1) fail(contract, `${path}.policy_reason`, "must contain at least 1 characters");
          if ((item as string).length > 240) fail(contract, `${path}.policy_reason`, "must contain at most 240 characters");
          break;
        }
      default: {
        fail(contract, `${path}.${key}`, "unexpected property");
      }
    }
  }
}

export function validateAttentionGroup(value: unknown, path: string, contract: string, refStack: Set<string>): void {
  if (!isRecord(value)) fail(contract, path, "expected object");
  const record = value as JsonRecord;
  if (!Object.hasOwn(record, "reason_code")) fail(contract, `${path}.reason_code`, "missing required property");
  if (!Object.hasOwn(record, "phase")) fail(contract, `${path}.phase`, "missing required property");
  if (!Object.hasOwn(record, "risk")) fail(contract, `${path}.risk`, "missing required property");
  if (!Object.hasOwn(record, "can_auto_fix")) fail(contract, `${path}.can_auto_fix`, "missing required property");
  if (!Object.hasOwn(record, "auto_fix_action")) fail(contract, `${path}.auto_fix_action`, "missing required property");
  for (const [key, item] of Object.entries(record)) {
    switch (key) {
        case "auto_fix_action": {
          validateUnion(contract, `${path}.auto_fix_action`, [
            () => {
              validateReference("AutoFixAction", validateAutoFixAction, item, `${path}.auto_fix_action`, contract, refStack);
            },
            () => {
              if (item !== null) fail(contract, `${path}.auto_fix_action`, "expected null");
            },
          ]);
          break;
        }
        case "can_auto_fix": {
          if (typeof item !== "boolean") fail(contract, `${path}.can_auto_fix`, "expected boolean");
          break;
        }
        case "phase": {
          validateReference("OperationPhase", validateOperationPhase, item, `${path}.phase`, contract, refStack);
          break;
        }
        case "reason_code": {
          validateReference("ReasonCode", validateReasonCode, item, `${path}.reason_code`, contract, refStack);
          break;
        }
        case "repositories": {
          if (!Array.isArray(item)) fail(contract, `${path}.repositories`, "expected array");
          (item as unknown[]).forEach((item, index) => {
            validateReference("AttentionRepository", validateAttentionRepository, item, `${`${path}.repositories`}[${index}]`, contract, refStack);
          });
          break;
        }
        case "risk": {
          validateReference("RiskLevel", validateRiskLevel, item, `${path}.risk`, contract, refStack);
          break;
        }
      default: {
        fail(contract, `${path}.${key}`, "unexpected property");
      }
    }
  }
}

